-- PH-512. Gerado por node scripts/gerar-migration-tms.js.

create table public.maquinas (
  item_id text primary key references public.items(id),
  golpe text not null unique,
  especies text[] not null
);
alter table public.maquinas enable row level security;
create policy leitura_maquinas on public.maquinas for select using (true);
grant select on public.maquinas to authenticated, anon;
grant all on public.maquinas to service_role;
-- O preço de venda é independente; buy_price continua NULL, logo comprar_item recusa.
alter table public.items alter column sell_price set expression as (
  case when kind = 'tm' then 1000 when kind = 'stone' then 500
  when kind in ('ball','potion','status_heal') then greatest(1, round(greatest(1, round(buy_price * 0.3)) * 0.5))
  else greatest(1, round(buy_price * 0.5)) end
);
create function public.preservar_golpes_de_maquina() returns trigger
language plpgsql set search_path=public,pg_temp as $$
begin
  new.golpes_de_maquina := array(select distinct g from unnest(old.golpes_de_maquina || coalesce(new.golpes_de_maquina,'{}')) g order by g);
  return new;
end;
$$;
create trigger preservar_golpes_de_maquina before update of golpes_de_maquina on public.pokemon_instances
  for each row execute function public.preservar_golpes_de_maquina();

create function public.ensinar_tm(p_item_id text, p_poke_id uuid) returns jsonb
language plpgsql security definer set search_path = public, pg_temp as $$
declare
  usuario uuid := auth.uid();
  maquina public.maquinas;
  poke public.pokemon_instances;
begin
  if usuario is null then raise exception 'Não autenticado' using errcode='28000'; end if;
  perform pg_advisory_xact_lock(hashtext(usuario::text));
  if exists(select 1 from public.game_sessions where user_id=usuario and (closed_at is null or flushing_since > now()-interval '2 minutes')) then
    raise exception 'Volte ao Hospital antes de ensinar uma TM.';
  end if;
  select * into maquina from public.maquinas where item_id=p_item_id;
  if not found then raise exception 'TM desconhecida.'; end if;
  select * into poke from public.pokemon_instances where id=p_poke_id and user_id=usuario and location in ('team','bag') for update;
  if not found then raise exception 'POKE não pertence à sua equipe ou mochila.'; end if;
  if not (poke.species_id=any(maquina.especies)) then raise exception 'Este POKE não aprende esta TM.'; end if;
  if maquina.golpe=any(poke.golpes_de_maquina) then
    return jsonb_build_object('ok',true,'mensagem','Este POKE já aprendeu esta TM. Nenhum item consumido.');
  end if;
  if exists(select 1 from public.species_moves where species_id=poke.species_id and move_id=maquina.golpe and level_req<=poke.level) then
    raise exception 'Este POKE já conhece o golpe.';
  end if;
  update public.player_items set quantity=quantity-1,updated_at=now()
    where user_id=usuario and item_id=p_item_id and quantity>0 and not locked;
  if not found then raise exception 'TM ausente ou trancada.'; end if;
  update public.pokemon_instances set
    golpes_de_maquina=array_append(golpes_de_maquina,maquina.golpe),
    unlocked_abilities=array_append(coalesce(unlocked_abilities,'{}'),maquina.golpe)
    where id=p_poke_id;
  update public.players set updated_at=now() where user_id=usuario;
  return jsonb_build_object('ok',true,'mensagem','TM consumida. Golpe aprendido permanentemente; selecione-o na ficha do POKE.');
end;
$$;
revoke all on function public.ensinar_tm(text,uuid) from public,anon;
grant execute on function public.ensinar_tm(text,uuid) to authenticated;

create table public.creditos_tm (
  user_id uuid not null references public.players(user_id) on delete cascade,
  origem text not null,
  item_id text not null references public.maquinas(item_id),
  primary key(user_id,origem,item_id)
);
alter table public.creditos_tm enable row level security;
grant all on public.creditos_tm to service_role;
create function public.creditar_drop_tm(p_user_id uuid,p_item_id text,p_qtd integer,p_origem text)
returns void language plpgsql security definer set search_path=public,pg_temp as $$
begin
  if p_qtd is null or p_qtd<=0 or p_qtd>1000000 or p_origem is null then raise exception 'Crédito inválido'; end if;
  perform pg_advisory_xact_lock(hashtext(p_user_id::text));
  if not found then return; end if;
    on conflict(user_id,item_id) do update set quantity=public.player_items.quantity+excluded.quantity,updated_at=now();
end;
$$;
revoke all on function public.creditar_drop_tm(uuid,text,integer,text) from public,anon,authenticated;
grant execute on function public.creditar_drop_tm(uuid,text,integer,text) to service_role;

